        att_term_move_AGENT: "Move to the office agent",
        att_term_move_DIRECT_body: "It connects through the office agent now. Moved, it sends its scans itself, over the office's internet connection, and the agent stops reading it at its next check-in, once it has sent what it already read. Its scans and history stay, each stored once. What to set on it is shown next.",
        att_term_move_AGENT_body: "It connects straight to Nizmo now. Moved, Nizmo stops taking its calls at once, and the office agent reads it from where it stopped once it reports this serial number. Its scans and history stay. Turn `Cloud Server Setting` off on the terminal, so it stops calling Nizmo.",
        att_term_move_AGENT_HIKVISION_body: "It connects straight to Nizmo now. Moved, Nizmo stops taking its calls at once, and the office agent reads it once it reports this serial number: add the terminal to the agent's `agent.json`, with the user made on it for the agent. The agent reads Hikvision terminals from version `0.3.0`, and each agent's version is on its card here. Its scans and history stay, each stored once. Turn `HTTP Listening` off on the terminal, so it stops calling Nizmo.",
