        face_consent_title: "Face verification: your consent",
        face_consent_body: "Your employer asks you to verify your face when you check in.\n\n• The app takes a few photos of your face to set it up. It turns them into numbers that describe your face and keeps those numbers only on this phone, locked by the phone's secure hardware. The setup photos are deleted at once.\n• At each check-in the app compares your face with those numbers on the phone. Only the result (matched or not) is sent. No photo is taken at ordinary check-ins.\n• One verification photo is sent and kept on the server, encrypted, so that a person can confirm it is really you. It is never on your profile. Only your company's Admin, HR (people allowed to approve face verification) and the system's Super Admin can see it, and every view is recorded.\n• If a check-in fails the face check three times, the last photo taken is sent with it for review and deleted once it is decided.\n• You can withdraw your consent at any time in the app. Your phone's face data becomes unreadable, your photos are deleted, and you check in without face verification. Nothing else about your employment changes.",
